// RegisterTools registers the FedEx MCP surface:
//
//   - one typed tool per FedEx REST operation (fixed method and path, JSON
//     request body only), read-only or write according to the same allowlist
//     the HTTP client enforces;
//   - ship_bulk, which creates up to 50 shipments from inline requests;
//   - a fixed set of local-data commands (address book, archive, spend,
//     manifest, rate shop, track diff) with per-tool flag allowlists; and
//   - context.
//
// There is no generic endpoint executor, no raw CLI argument passthrough, no
// SQL tool, and no tool that reads or writes caller-chosen file paths.
func RegisterTools(s *server.MCPServer) {
	registerEndpointTools(s)
	registerShipBulkTool(s)
	registerLocalCommandTools(s)
	s.AddTool(
		mcplib.NewTool("context",
			mcplib.WithDescription("Get API domain context: resource taxonomy, auth requirements, write-safety rules, and which tool covers which workflow. Call this first."),
			mcplib.WithReadOnlyHintAnnotation(true),
			mcplib.WithDestructiveHintAnnotation(false),
			mcplib.WithIdempotentHintAnnotation(true),
			mcplib.WithOpenWorldHintAnnotation(false),
		),
		handleContext,
	)
}

func newMCPClient() (*client.Client, error) {
	home, _ := os.UserHomeDir()
	cfgPath := filepath.Join(home, ".config", "fedex-pp-cli", "config.toml")
	cfg, err := config.Load(cfgPath)
	if err != nil {
		return nil, fmt.Errorf("loading config: %w", err)
	}
	return client.New(cfg, 30*time.Second, 0), nil
}

